// ============================================================================
// AES-128 Masked Encryption Core — First-Order Boolean Masking
//
// Architecture:
//   Same iterative 128-bit datapath as the unpatched core, but all state
//   register values are masked: state_reg = real_state ⊕ mask.
//
// Masking scheme:
//   - A 128-bit random mask M is generated by the PRNG before each encryption.
//   - 16 byte-level masks: m[i] = M[127-8*i -: 8] for i=0..15
//   - Cycle 0:  state_reg = (PT ⊕ Key0) ⊕ M  (masked initial AddRoundKey)
//   - Rounds 1-10:
//     * SubBytes: uses masked S-Box tables (precomputed per encryption)
//       Input mask per byte  = m_in[i]  (current mask on state byte i)
//       Output mask per byte = m_out[i] (new mask after S-box)
//       Result: S(x) ⊕ m_out[i]
//     * ShiftRows: permutes masked bytes AND their corresponding masks
//     * MixColumns: linear over GF(2^8), so:
//       MixColumns(state ⊕ mask) = MixColumns(state) ⊕ MixColumns(mask)
//       We compute MixColumns(mask_after_SR) in parallel to track the mask
//     * AddRoundKey: XOR with round key (mask unchanged since XOR is linear)
//   - After round 10: unmask ciphertext = state_reg ⊕ final_mask
//
// Latency:
//   - 256 cycles for masked S-box table init (once per encryption)
//   - 11 cycles for encryption (same as unpatched)
//   - Total: ~267 + small overhead cycles per block
//
// Security:
//   First-order secure: every intermediate register value is statistically
//   independent of the unmasked value (uniform XOR with random mask).
//   Power consumption at any single point in time reveals no information
//   about the secret key to a first-order DPA/CPA attacker.
//
// Interface: Same as aes128_core.sv plus PRNG seed input
// ============================================================================

module aes128_masked_core (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         start,
    input  logic [127:0] plaintext,
    input  logic [127:0] key,
    input  logic [127:0] prng_seed,    // seed for PRNG (must be non-zero)
    output logic [127:0] ciphertext,
    output logic         busy,
    output logic         done
);

    // ========================================================================
    // FSM States
    // ========================================================================
    typedef enum logic [2:0] {
        S_IDLE       = 3'd0,  // waiting for start
        S_INIT_PRNG  = 3'd1,  // wait for PRNG to produce M0
        S_WAIT_PRNG  = 3'd2,  // latch PRNG output as mask_out, trigger sbox init
        S_INIT_SBOX  = 3'd3,  // wait for masked S-box tables to build (256 cycles)
        S_ROUND_SB   = 3'd4,  // S-box lookup (1 cycle registered read)
        S_ROUND_CALC = 3'd5   // ShiftRows + MixColumns + AddRoundKey
    } state_t;

    state_t fsm_state;

    // ========================================================================
    // Internal registers
    // ========================================================================
    logic [127:0] state_reg;      // masked AES state (real_state ⊕ mask)
    logic [127:0] mask_reg;       // current 128-bit mask on state_reg
    logic [127:0] key_reg;        // current round key (NOT masked — key schedule is deterministic)
    logic [3:0]   round_cnt;      // round counter (0–10)

    // ========================================================================
    // PRNG — generates 128-bit random masks
    // ========================================================================
    logic [127:0] prng_out;
    logic         prng_advance;

    prng_lfsr u_prng (
        .clk     (clk),
        .rst_n   (rst_n),
        .seed_in (prng_seed),
        .advance (prng_advance),
        .rng_out (prng_out)
    );

    // We need two sets of masks:
    //   mask_in[i]  = current mask on state byte i (before SubBytes)
    //   mask_out[i] = new mask after SubBytes (from a second PRNG draw)
    // For simplicity, we use:
    //   mask_in  = mask_reg (the current state mask)
    //   mask_out = prng_out (a fresh PRNG output, drawn at round start)
    // After SubBytes, the mask on each byte becomes mask_out[i].

    logic [127:0] mask_after_sb;  // = rearranged mask_out bytes

    // ========================================================================
    // Masked S-Box instances (16 for state)
    // All share the same m_in/m_out per byte position (init in parallel)
    // ========================================================================
    logic        sbox_init_start;
    logic [15:0] sbox_init_busy;
    logic [127:0] after_subbytes_masked;  // S(x) ⊕ m_out for each byte

    // S-box mask_out register (latched from PRNG at start of each round)
    logic [127:0] mask_out_reg;

    genvar gi;
    generate
        for (gi = 0; gi < 16; gi++) begin : gen_masked_sbox
            aes_masked_sbox u_msbox (
                .clk        (clk),
                .rst_n      (rst_n),
                .init_start (sbox_init_start),
                .m_in       (mask_reg[127 - 8*gi -: 8]),
                .m_out      (mask_out_reg[127 - 8*gi -: 8]),
                .init_busy  (sbox_init_busy[gi]),
                .data_in    (state_reg[127 - 8*gi -: 8]),
                .data_out   (after_subbytes_masked[127 - 8*gi -: 8])
            );
        end
    endgenerate

    logic any_sbox_busy;
    assign any_sbox_busy = |sbox_init_busy;

    // ========================================================================
    // Key expansion (same as unpatched — key schedule is not masked)
    // ========================================================================
    logic [127:0] next_round_key;

    aes_key_expand u_key_expand (
        .key_in  (key_reg),
        .round   (round_cnt),
        .key_out (next_round_key)
    );

    // ========================================================================
    // ShiftRows on masked state (same permutation as unpatched)
    // Also permute the mask bytes identically
    // ========================================================================
    logic [127:0] after_shiftrows;
    logic [127:0] mask_after_sr;

    // ShiftRows permutation for a 128-bit vector
    function automatic logic [127:0] shift_rows_fn(input logic [127:0] din);
        logic [127:0] out;
        // Row 0: no shift (bytes 0, 4, 8, 12)
        out[127:120] = din[127:120];  // byte 0
        out[95:88]   = din[95:88];    // byte 4
        out[63:56]   = din[63:56];    // byte 8
        out[31:24]   = din[31:24];    // byte 12
        // Row 1: shift left by 1 (bytes 1,5,9,13)
        out[119:112] = din[87:80];    // byte 5 -> pos 1
        out[87:80]   = din[55:48];    // byte 9 -> pos 5
        out[55:48]   = din[23:16];    // byte 13 -> pos 9
        out[23:16]   = din[119:112];  // byte 1 -> pos 13
        // Row 2: shift left by 2 (bytes 2,6,10,14)
        out[111:104] = din[47:40];    // byte 10 -> pos 2
        out[79:72]   = din[15:8];     // byte 14 -> pos 6
        out[47:40]   = din[111:104];  // byte 2 -> pos 10
        out[15:8]    = din[79:72];    // byte 6 -> pos 14
        // Row 3: shift left by 3 (bytes 3,7,11,15)
        out[103:96]  = din[7:0];      // byte 15 -> pos 3
        out[71:64]   = din[103:96];   // byte 3 -> pos 7
        out[39:32]   = din[71:64];    // byte 7 -> pos 11
        out[7:0]     = din[39:32];    // byte 11 -> pos 15
        return out;
    endfunction

    assign after_shiftrows = shift_rows_fn(after_subbytes_masked);
    assign mask_after_sr   = shift_rows_fn(mask_out_reg);

    // ========================================================================
    // MixColumns on masked state and mask (linear property)
    //   MixColumns(state_masked) = MixColumns(real_state ⊕ mask_after_sr)
    //                            = MixColumns(real_state) ⊕ MixColumns(mask_after_sr)
    // So new mask = MixColumns(mask_after_sr)
    // ========================================================================
    logic [127:0] after_mixcolumns;
    logic [127:0] mask_after_mc;

    aes_mixcolumns u_mixcol_state (
        .state_in  (after_shiftrows),
        .state_out (after_mixcolumns)
    );

    aes_mixcolumns u_mixcol_mask (
        .state_in  (mask_after_sr),
        .state_out (mask_after_mc)
    );

    // ========================================================================
    // AddRoundKey (linear — mask unchanged)
    //   (state ⊕ mask) ⊕ round_key = (state ⊕ round_key) ⊕ mask
    // ========================================================================
    logic [127:0] after_addroundkey;
    logic [127:0] mask_after_ark;

    always_comb begin
        if (round_cnt == 4'd10) begin
            // Final round: no MixColumns
            after_addroundkey = after_shiftrows ^ next_round_key;
            mask_after_ark    = mask_after_sr;
        end else begin
            // Rounds 1-9: with MixColumns
            after_addroundkey = after_mixcolumns ^ next_round_key;
            mask_after_ark    = mask_after_mc;
        end
    end

    // ========================================================================
    // S-Box for key expansion (unmasked, 4 instances — reuse from stage1)
    // Key schedule is deterministic and doesn't need masking protection
    // (The key is constant; masking protects the data-dependent state)
    // ========================================================================
    // Key expansion already uses aes_sbox internally via aes_key_expand

    // ========================================================================
    // FSM & Datapath Control
    // ========================================================================
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            fsm_state       <= S_IDLE;
            state_reg       <= 128'b0;
            mask_reg        <= 128'b0;
            key_reg         <= 128'b0;
            round_cnt       <= 4'd0;
            ciphertext      <= 128'b0;
            done            <= 1'b0;
            sbox_init_start <= 1'b0;
            prng_advance    <= 1'b0;
            mask_out_reg    <= 128'b0;
        end else begin
            done            <= 1'b0;
            sbox_init_start <= 1'b0;
            prng_advance    <= 1'b0;

            case (fsm_state)
                // ────────────────────────────────────────────────────────
                S_IDLE: begin
                    if (start) begin
                        key_reg      <= key;
                        state_reg    <= plaintext;
                        prng_advance <= 1'b1;  // advance to get M0
                        fsm_state    <= S_INIT_PRNG;
                    end
                end

                // ────────────────────────────────────────────────────────
                S_INIT_PRNG: begin
                    // prng_out is now M0
                    state_reg    <= (state_reg ^ key_reg) ^ prng_out;
                    mask_reg     <= prng_out;
                    round_cnt    <= 4'd1;
                    prng_advance <= 1'b1;  // advance to get M1 (first round sbox mask_out)
                    fsm_state    <= S_WAIT_PRNG;
                end

                // ────────────────────────────────────────────────────────
                S_WAIT_PRNG: begin
                    // prng_out is now the new S-box output mask
                    mask_out_reg    <= prng_out;
                    sbox_init_start <= 1'b1;
                    fsm_state       <= S_INIT_SBOX;
                end

                // ────────────────────────────────────────────────────────
                S_INIT_SBOX: begin
                    if (!any_sbox_busy && !sbox_init_start) begin
                        // S-box tables ready — perform S-box lookup
                        fsm_state <= S_ROUND_SB;
                    end
                end

                // ────────────────────────────────────────────────────────
                S_ROUND_SB: begin
                    // after_subbytes_masked is now valid (1-cycle BRAM read latency)
                    fsm_state <= S_ROUND_CALC;
                end

                // ────────────────────────────────────────────────────────
                S_ROUND_CALC: begin
                    if (round_cnt == 4'd10) begin
                        // Final round complete — unmask and output
                        ciphertext <= after_addroundkey ^ mask_after_ark;
                        done       <= 1'b1;
                        fsm_state  <= S_IDLE;
                        round_cnt  <= 4'd0;
                    end else begin
                        // Store result and update mask tracking
                        state_reg    <= after_addroundkey;
                        mask_reg     <= mask_after_ark;
                        key_reg      <= next_round_key;
                        round_cnt    <= round_cnt + 4'd1;
                        prng_advance <= 1'b1;  // advance to get next round's sbox mask_out
                        fsm_state    <= S_WAIT_PRNG;
                    end
                end

                // ────────────────────────────────────────────────────────
                default: begin
                    fsm_state <= S_IDLE;
                end
            endcase
        end
    end

    // ========================================================================
    // Busy signal — high whenever not idle
    // ========================================================================
    assign busy = (fsm_state != S_IDLE);

endmodule
